import numpy as np
from scipy.optimize import minimize
import time

def equidistant_points_polygon20() -> np.ndarray:
    # Deadline guard
    start_time = time.time()
    deadline = start_time + 550.0  # 550s limit, 50s margin
    
    n = 20
    
    def compute_polygon(params):
        # params: 8 values (x0,y0,x1,y1,x2,y2,x3,y3)
        # These are the 4 base points in the first 72-degree sector
        # We assume 5-fold rotational symmetry
        # The full set of points is generated by rotating these 4 points by 72, 144, 216, 288 degrees
        # We must ensure they are in cyclic order.
        # Let's assume the angles of the base points are in (0, 72) and sorted.
        
        p0 = np.array([params[0], params[1]])
        p1 = np.array([params[2], params[3]])
        p2 = np.array([params[4], params[5]])
        p3 = np.array([params[6], params[7]])
        
        base_points = np.array([p0, p1, p2, p3])
        
        # Check if they are in a valid sector and ordered
        # We will enforce this by projecting or just letting the optimizer work in a constrained space?
        # Simpler: Just generate all 20 points and check convexity/order.
        # If invalid, return a penalty.
        
        all_points = []
        for k in range(5):
            angle = k * 2 * np.pi / 5
            c = np.cos(angle)
            s = np.sin(angle)
            R = np.array([[c, -s], [s, c]])
            for p in base_points:
                all_points.append(R @ p)
                
        poly = np.array(all_points)
        
        # Check if the points are in cyclic order around the origin
        # Calculate angles
        angles = np.arctan2(poly[:, 1], poly[:, 0])
        # Sort angles to check if the generated order matches sorted order
        # The generated order is p0, p1, p2, p3, R p0, ...
        # We need the angles to be increasing (mod 2pi)
        # Let's check if the sequence of angles is monotonic (with wrap around)
        
        # Normalize angles to [0, 2pi)
        angles = np.mod(angles, 2 * np.pi)
        
        # Check convexity and cyclic order
        # A polygon is convex and in cyclic order if the cross product of consecutive edges is positive
        # and the angles are monotonic
        
        # First, check if the points are distinct
        # And check convexity
        
        # Compute cross products
        valid = True
        for i in range(n):
            p_prev = poly[(i - 1) % n]
            p_curr = poly[i]
            p_next = poly[(i + 1) % n]
            
            e1 = p_curr - p_prev
            e2 = p_next - p_curr
            cross = e1[0] * e2[1] - e1[1] * e2[0]
            
            if cross <= 1e-8: # Strictly convex, allow small epsilon
                valid = False
                break
                
            # Also check if the point is "outside" the convex hull? 
            # Cross product check for all consecutive triples ensures strict convexity for a simple polygon.
            # But we also need to ensure it's a simple polygon (no self-intersections).
            # For a star-shaped polygon generated by rotating a set of points in a sector, 
            # if the points in the sector are ordered by angle, it should be simple.
            
        # Check angle monotonicity in the sector
        # The base points should have angles in [0, 2pi/5)
        base_angles = np.mod(np.arctan2(base_points[:, 1], base_points[:, 0]), 2 * np.pi)
        # They should be sorted
        if not np.all(np.diff(base_angles) > 1e-6):
             # They might wrap around? No, they are in the first sector.
             # If they are not sorted, the polygon might be twisted.
             valid = False
             
        if not valid:
            return None, 0.0

        return poly, 1.0

    def vertex_score(v, poly):
        # v is the vertex index
        # Compute distances from v to all other vertices
        dists = np.linalg.norm(poly - poly[v], axis=1)
        dists[v] = np.inf # Exclude self
        
        # Sort distances
        sorted_dists = np.sort(dists)
        
        # Check min distance
        if sorted_dists[0] < 0.05:
            return 0.0
            
        # Find k: first index minimizing gap
        gaps = np.diff(sorted_dists)
        k = np.argmin(gaps)
        
        D = (sorted_dists[k] + sorted_dists[k+1]) / 2.0
        
        if D < 0.1:
            return 0.0
            
        # Select 4 distances
        if k == 0:
            d_sel = sorted_dists[0:4]
        elif k == 17:
            d_sel = sorted_dists[15:19]
        else:
            d_sel = sorted_dists[k-1:k+3]
            
        # Compute raw
        ratios = np.maximum(d_sel / D, D / d_sel)
        raw = np.mean(ratios)
        
        score = min(1.0, 1.0 / raw)
        return score

    def total_score(poly):
        # Normalize
        centroid = np.mean(poly, axis=0)
        poly_centered = poly - centroid
        dists_to_centroid = np.linalg.norm(poly_centered, axis=1)
        mean_dist = np.mean(dists_to_centroid)
        
        if mean_dist <= 0.01:
            return 0.0
            
        poly_normalized = poly_centered / mean_dist
        
        # Compute vertex scores
        scores = []
        for i in range(n):
            s = vertex_score(i, poly_normalized)
            scores.append(s)
            
        return min(scores)

    def objective(params):
        poly, valid = compute_polygon(params)
        if not valid:
            return 1e6 # Penalty
            
        score = total_score(poly)
        return -score # Maximize score

    # Initial guess: Regular 20-gon
    # Base points for regular 20-gon in the first sector
    # Angles: 0, 18, 36, 54 degrees? No, 20 vertices, 72 deg per 5 vertices.
    # Vertices in sector: 0, 1, 2, 3.
    # Angles: 0, 2pi/20, 4pi/20, 6pi/20.
    # Radii: 1.
    
    init_params = []
    for i in range(4):
        angle = i * 2 * np.pi / 20
        x = np.cos(angle)
        y = np.sin(angle)
        init_params.append(x)
        init_params.append(y)
        
    init_params = np.array(init_params)
    
    # Optimization
    # Use Nelder-Mead
    result = minimize(objective, init_params, method='Nelder-Mead', 
                      options={'xatol': 1e-6, 'fatol': 1e-6, 'maxiter': 10000})
    
    best_params = result.x
    best_score = -result.fun
    
    # Check time
    if time.time() > deadline:
        # Return the best found so far
        poly, _ = compute_polygon(best_params)
        if poly is not None:
            return poly
        else:
            # Fallback to regular polygon
            angles = np.linspace(0.0, 2.0 * np.pi, n, endpoint=False)
            return np.stack([np.cos(angles), np.sin(angles)], axis=1)
            
    # Try a few more restarts if time permits
    # But Nelder-Mead might be stuck.
    # Let's just return the result.
    
    poly, _ = compute_polygon(best_params)
    if poly is not None:
        return poly
    else:
        angles = np.linspace(0.0, 2.0 * np.pi, n, endpoint=False)
        return np.stack([np.cos(angles), np.sin(angles)], axis=1)
